def choose_move(observation):
    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def first_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            a, b = x[0], x[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [a, b]
        return None

    def get_agent_pos(obs):
        for k in ("position", "pos", "agent_pos", "agent_position", "self_pos", "location", "loc"):
            p = first_pair(obs.get(k, None))
            if p is not None:
                return p
        me = obs.get("self", None)
        if isinstance(me, dict):
            for k in ("position", "pos", "location", "loc"):
                p = first_pair(me.get(k, None))
                if p is not None:
                    return p
        return [0, 0]

    def as_points(x):
        pts = []
        if x is None:
            return pts
        if isinstance(x, dict):
            for v in x.values():
                pts.extend(as_points(v))
            return pts
        if isinstance(x, (list, tuple)):
            if len(x) >= 2 and isinstance(x[0], (int, float)) and isinstance(x[1], (int, float)):
                pts.append([x[0], x[1]])
            else:
                for v in x:
                    pts.extend(as_points(v))
        return pts

    def score_move(pos, mv, targets, threats, goal_sign=1):
        nx = pos[0] + mv[0]
        ny = pos[1] + mv[1]
        s = 0.0

        if targets:
            best = None
            for t in targets:
                d = abs(t[0] - nx) + abs(t[1] - ny)
                if best is None or d < best:
                    best = d
            if best is not None:
                s += 8.0 / (1.0 + best)

        if threats:
            worst = None
            for t in threats:
                d = abs(t[0] - nx) + abs(t[1] - ny)
                if worst is None or d < worst:
                    worst = d
            if worst is not None:
                if worst == 0:
                    s -= 1000.0
                else:
                    s -= 6.0 / worst

        # mild preference for movement over idling
        if mv[0] == 0 and mv[1] == 0:
            s -= 0.05

        # goal_sign used to bias towards positive/negative resource territory if available
        s += 0.01 * (mv[0] * goal_sign + mv[1] * goal_sign)
        return s

