                best_score = sc
                best = mv
        return [clamp(best[0]), clamp(best[1])]

    # If only threats are known, keep distance.
    if threats:
        best = [0, 0]
        best_score = None
        for mv in candidates:
            sc = score_move(pos, mv, [], threats, -1)
            if best_score is None or sc > best_score:
                best_score = sc
                best = mv
        return [clamp(best[0]), clamp(best[1])]

    # Territory control / unknown: drift toward center, else a mild deterministic sweep.
